# -*- coding: utf-8 -*-
"""English translations, batch 18 (40 figures)."""
EN = {
"罗以": dict(lesson="Faith across generations, passed down through the line",
 summary="Timothy's grandmother, of genuine faith.",
 witness="Lois was Timothy's grandmother, whose 'sincere faith' first dwelt in her own heart, then was passed to her daughter Eunice, and on to her grandson Timothy. Faith handed down through three generations produced a faithful gospel co-worker. A spiritual inheritance can be passed on like this, generation by generation.",
 follow=["Holding 'sincere faith,' a spiritual example across generations","Actively taking part in nurturing grandchildren's faith"],
 caution=["Not despising a grandparent's influence on grandchildren's spiritual life"],
 applications=["Influence both children and grandchildren with genuine faith","Actively take part in the faith nurture of the next and next-next generation","Keep praying for descendants' spiritual life"],
 prayer="Lord, Lois' faith passed through three generations and bore fruit in Timothy. Make me hold sincere faith, a spiritual example to children and grandchildren, passing faith down generation by generation. Amen."),
"友尼基": dict(lesson="Passing true faith to your child with your own hands",
 summary="Timothy's mother, a devout Jewish believer.",
 witness="Eunice was Timothy's mother, a devout Jewish believer. Paul said Timothy's 'sincere faith' first dwelt in his grandmother Lois and his mother Eunice. She taught Timothy the Scriptures and true faith from childhood, raising Paul's most capable spiritual son.",
 follow=["Raising children in Scripture and true faith from childhood","Being an example with her own 'sincere faith'"],
 caution=["Not wholly outsourcing the responsibility of passing faith to others"],
 applications=["Lead your child to know the Scriptures and the true God from childhood","Be an example by a genuine (sincere) life of faith","Trust the family's faith nurture has far-reaching influence"],
 prayer="Lord, Eunice passed sincere faith to Timothy. Make me influence my family with a genuine life of faith, planting Your word in the next generation's heart from childhood. Amen."),
"亚拿尼亚（撒非喇之夫）": dict(lesson="Lying to the Holy Spirit for a good name",
 summary="Who with his wife Sapphira conspired to deceive the Holy Spirit and died.",
 witness="Ananias and his wife Sapphira sold a field and secretly kept back part, yet claimed to have given it all. The problem was not keeping money (which was free), but 'lying to the Holy Spirit,' lying for a good name. Peter exposed it in a word, and he fell dead on the spot. Falsehood before God is far more terrible than poverty.",
 follow=[],
 caution=["Lying in giving and service for a good name","Thinking one can do surface work even toward God"],
 applications=["Give and serve within your means and honestly, not chasing vanity","Be wholly honest before God, no surface work","Do good of one heart as a couple, not conspire in falsehood"],
 prayer="Lord, Ananias died lying to the Holy Spirit for a good name. Make me wholly honest before You, giving and serving without chasing vanity, doing no surface work toward You. Amen."),
"丢特腓": dict(lesson="Loving to be first, shutting the door of hospitality",
 summary="One who loved to be first and would not receive the brothers.",
 witness="Diotrephes is the one in 3 John who 'loved to be first.' He would not receive the traveling preachers, forbade others to receive them, put those who did out of the church, and even talked maliciously against the apostle John. Loving power, exclusion, and intolerance made him a negative example in the church.",
 follow=[],
 caution=["Loving to be first, intolerant of others","Not receiving the brothers, and hindering others from receiving them","Talking maliciously against a spiritual elder"],
 applications=["Don't covet the position and control of 'being first'","Open the door of hospitality, not excluding outside members","Respect spiritual elders, not maligning people with evil words"],
 prayer="Lord, Diotrephes loved to be first and would not receive the brothers. Remove from me the love of power and exclusion, make me humbly hospitable and respectful of members, not coveting control. Amen."),
"低米丢": dict(lesson="Everyone gives him a good testimony",
 summary="One to whom everyone gave a good testimony.",
 witness="Demetrius is the one commended in 3 John, who 'has a good testimony from everyone, and from the truth itself.' His character won the community's unanimous good word, and even the truth itself confirmed him. How precious is one whose reputation stands on the truth.",
 follow=["Standing on the truth, winning everyone's genuine good word","Letting his testimony withstand the confirmation of truth"],
 caution=[],
 applications=["Seek a reputation that stands on truth, not flattery","Let your character withstand the test of both people and truth","Be one who 'has a good testimony'"],
 prayer="Lord, Demetrius had the testimony of everyone and of the truth. Make me stand on the truth, living a good testimony that withstands testing, glorifying Your name. Amen."),
"米迦勒": dict(lesson="The archangel, fighting for God's people",
 summary="The archangel who fought the dragon.",
 witness="Michael is the archangel who fought for Israel in Daniel, who in Jude 'did not dare pronounce a blasphemous judgment' while disputing with the devil over Moses' body, and who in Revelation led the heavenly host against the great dragon. He had great power, yet never overstepped, acting only by the Lord's authority. The greater the power, the more one should be humble and obedient.",
 follow=["Great in power yet not overstepping, acting by the Lord's authority","Faithfully fighting for God's people"],
 caution=["Not treating spiritual powers with slander and contempt"],
 applications=["The more powerful, the more humble; don't overstep on your own","In spiritual battle, rely on the Lord's authority, not self-boasting","Treat spiritual things with a reverent attitude"],
 prayer="Lord, the archangel Michael was great in power yet humbly obedient to You. Make me, whatever power I have, never overstep, standing by Your authority, faithfully fighting for Your people. Amen."),
"尼哥拉党人": dict(lesson="A teaching of compromise the Lord hates",
 summary="A heretical group the Lord hates.",
 witness="The Nicolaitans were a heretical group in the early church, mentioned twice by the Lord in His letters to Ephesus and Pergamum—the Ephesian church 'hated their works,' which accorded with the Lord's heart; Pergamum, however, tolerated them. They likely held that one could compromise with idolatry and immorality. The Lord plainly said: this is what I hate.",
 follow=[],
 caution=["Advocating compromise with idols, immorality, and the world","Bringing 'indulgence is fine' teaching into the church"],
 applications=["Be alert to 'teaching' that leads people to compromise with the world","Like the Ephesian church, hate sinful works","Don't tolerate heresy and indulgence that corrupt the community"],
 prayer="Lord, the works of the Nicolaitans are what You hate. Make me discern and reject teaching that leads to compromise with the world, hating sin yet loving sinners, guarding the community's purity. Amen."),
"耶洗别（推雅推喇）": dict(lesson="The 'Jezebel' in the church, luring to compromise",
 summary="The woman in the church of Thyatira who called herself a prophetess and seduced people.",
 witness="She is the woman in the church of Thyatira in Revelation 'who calls herself a prophetess, Jezebel,' who seduced the Lord's servants into immorality and eating things offered to idols. The Lord called her by the name of the wicked queen of the Old Testament, warning of the danger of 'seducing people inside the church to compromise and commit immorality with the world.' The Lord gave her a chance to repent, but she would not.",
 follow=[],
 caution=["Self-appointing authority within the church, luring to compromise","Seducing believers to mingle with the world and idols","Still refusing to turn back though given a chance to repent"],
 applications=["Be alert to voices and influences inside the church that 'lure to compromise'","Don't mingle with the values of the world and idols","Treasure and seize the chance to repent God gives"],
 prayer="Lord, the 'Jezebel' of Thyatira lured people to compromise and ruin. Make me discern and stay far from influences inside the church that lure to compromise, not mingling with the world, treasuring the chance to repent You give. Amen."),
"龙": dict(lesson="The ancient serpent, the devil, an enemy already defeated",
 summary="The great red dragon, that is the ancient serpent the devil, hostile to God and the church.",
 witness="The dragon is the great red dragon of Revelation, 'that ancient serpent, who is called the devil and Satan, the deceiver of the whole world.' It tried to devour the child about to be born, fought the archangel Michael, and persecuted the saints. Yet it has been cast down, its days are few, and it will finally be thrown into the lake of fire. Fierce and furious, it is an enemy already defeated, finally trodden underfoot.",
 follow=[],
 caution=["(Recognize the enemy) it is the source of deception, accusation, and persecution","Its fury comes from knowing its days are few"],
 applications=["Recognize the real enemy is the devil, not people","Overcome it by the blood of the Lamb and the word of testimony","Stand firm in its furious persecution, knowing it is already defeated"],
 prayer="Lord, though the ancient serpent the devil rages, You have decreed its end. Make me recognize the real enemy, overcome it by the Lamb's blood and the true word, and stand firm in persecution. Amen."),
"兽": dict(lesson="Blasphemy and persecution finally end in the lake of fire",
 summary="The beast that comes up from the sea, hostile to God and blaspheming God.",
 witness="The 'beast' in Revelation comes up from the sea, receives the dragon's authority, opens its mouth to blaspheme God, makes war on the saints and conquers them, and forces all peoples to worship it and receive its mark. It symbolizes the powers and regimes on earth hostile to God, rampant for a time, but ending thrown into the lake of fire. The most arrogant persecuting power—God has already decreed its end.",
 follow=[],
 caution=["Blaspheming God, persecuting the saints, forcing allegiance","Coercing people to worship and receive a mark by power"],
 applications=["Recognize and resist powers and value-systems hostile to God","Rather suffer harm than bow to the 'beast' or receive its mark","Hold firm in persecution, trusting the enemy's end is decreed"],
 prayer="Lord, the blaspheming, persecuting beast ends in the lake of fire. Make me recognize and resist powers hostile to You, rather suffer than yield to it, firmly trusting You have decreed its end. Amen."),
"假先知（启示录）": dict(lesson="Performing wonders to deceive, finally destroyed by God",
 summary="The false prophet who deceives the world with the beast.",
 witness="The false prophet in Revelation (also the beast that comes up from the earth) performs great signs, deceiving those who dwell on earth into worshipping the beast and its image. With a religious appearance and supernatural phenomena, it draws people to worship hostile to God, and is finally thrown with the beast into the lake of fire. The one who can do miracles is not necessarily from God—discern by truth.",
 follow=[],
 caution=["Deceiving people away from the true God with wonders and signs","In a religious cloak, leading people to worship idols and follow the beast"],
 applications=["Discern true from false by truth, not by signs and wonders","Beware deception in a spiritual cloak","Worship only the one true God, following no 'beast'"],
 prayer="Lord, the false prophet deceives with wonders and is finally destroyed. Give me a spirit that discerns by truth, undeceived by signs, worshipping only You, the one true God. Amen."),
"大淫妇巴比伦": dict(lesson="The prosperous, immoral 'Babylon' falls in an hour",
 summary="The great prostitute symbolizing the city-state hostile to God.",
 witness="Babylon the great prostitute is the symbol in Revelation of the city-state riding the scarlet beast, 'seated on many waters,' representing the world system rebellious against God, luxurious, immoral, and persecuting the saints. She is utterly prosperous, yet falls in a single hour—'fallen, fallen is Babylon the great.' God calls His people: come out of her, lest you share in her sins and her plagues.",
 follow=[],
 caution=["Drunk on the prosperity and immorality of the world system rebellious against God","Mingling in 'Babylon's' sins, coveting her glory"],
 applications=["Separate from the value system rebellious against God","Don't covet or be drunk on the world's prosperity and immorality","Remember even the most prosperous system will fall in an hour"],
 prayer="Lord, Babylon the great prostitute, utterly prosperous, fell in an hour. Call me out of her, that I not be stained by the world's immorality and rebellion, nor covet glory that will fall. Amen."),
"两个见证人": dict(lesson="Faithful in witness, killed and raised again",
 summary="The two witnesses clothed in sackcloth who preached, were killed, and rose again.",
 witness="The two witnesses in Revelation are clothed in sackcloth, preaching and bearing witness. Having finished their ministry, they were killed by the beast, their bodies displayed three and a half days while people rejoiced; yet God breathed life into them and they stood up and were taken to heaven. Faithful witnesses, though killed, God will raise and glorify—the end of those who witness for the Lord is in God's hands.",
 follow=["Faithfully bearing witness until the ministry entrusted is finished","Though harmed, still trusting God's power to raise the dead"],
 caution=[],
 applications=["Faithfully witness for the Lord, undaunted by opposition","Trust that those harmed for the Lord, God will raise and glorify","Stand firm when your witness is mocked and persecuted"],
 prayer="Lord, the two witnesses were faithful unto death, yet You raised them to heaven. Make me faithfully bear Your witness, and even when harmed, firmly trust Your resurrection power and glory. Amen."),
"以利米勒": dict(lesson="Leaving to escape famine, yet losing more",
 summary="Naomi's husband, who moved his family to Moab because of famine and died in a foreign land.",
 witness="Elimelech was Naomi's husband, a man of Bethlehem (which means 'house of bread'). When famine struck, he moved his family to sojourn in Moab, hoping to save his life and estate, but died in a foreign land, and his two sons died there too. To leave the land of God's inheritance to escape a passing trouble cost more than imagined.",
 follow=[],
 caution=["Leaving the land God gave to escape a present trouble","Replacing trust in God with calculations of self-preservation"],
 applications=["In trouble, first seek God's will, not only calculate self-preservation","Don't lightly leave the place God set you","Entrust the anxiety of livelihood to the God who provides"],
 prayer="Lord, Elimelech left Bethlehem to escape famine, yet lost more. Make me trust Your provision in trouble, not leaving the place You set me by calculations of self-preservation. Amen."),
"玛伦": dict(lesson="His death became the turning point of Ruth coming to the Lord",
 summary="Elimelech's son, Ruth's former husband, who died in Moab.",
 witness="Mahlon was Elimelech's eldest son, who married the Moabite Ruth and died childless in Moab. His early death seemed total loss, yet through it God brought Ruth back to Bethlehem and into God's people, an ancestor of David and Christ. God can bring unexpected redemption out of the deepest loss.",
 follow=[],
 caution=["(Background) the marriage and circumstances away from God's land are worth reflecting on"],
 applications=["Trust God can bring redemption out of loss and death","In what seems all loss, look to God's turning point","Remember your life's influence may far exceed what you see"],
 prayer="Lord, Mahlon died young, yet through it You brought Ruth into the line of salvation. Make me still trust You in loss, knowing You can bring unexpected redemption out of the deepest loss. Amen."),
"基连": dict(lesson="The next generation away from home, withered in a foreign land",
 summary="Elimelech's son, Orpah's husband, who died in Moab.",
 witness="Chilion was Elimelech's second son, who married Orpah in Moab but died there without leaving descendants. The migration his father made to escape trouble left this generation to wither in a foreign land. The previous generation's choices often deeply affect the next generation's circumstances.",
 follow=[],
 caution=["(An inheritance warning) the previous generation's choice to leave God's land affects the next"],
 applications=["Be aware that your choices affect your children's circumstances","Seek God's guidance for the family's direction","Don't let one generation's straying become the next generation's loss"],
 prayer="Lord, Chilion withered in foreign Moab. Guide the choices I make for my family, that I not let one generation's straying become the next generation's loss, leading my whole family in Your way. Amen."),
"亚希暖": dict(lesson="A wife who followed through affliction",
 summary="A Jezreelite, David's wife, Amnon's mother.",
 witness="Ahinoam was a Jezreelite, David's wife, Amnon's mother. She followed through the hard years of David's flight, and was once captured and rescued together at Ziklag. She was not illustrious, yet was a partner who shared David's hardships in his wandering days.",
 follow=["Sharing hardship with the one she loved in affliction","Quietly supporting, not seeking prominence"],
 caution=[],
 applications=["Don't leave a spouse or family in their hardship","Value the bond of following through affliction","Be faithful in inconspicuous support"],
 prayer="Lord, Ahinoam followed David through his wandering. Make me not leave those I love in affliction, but be one who shares hardship and quietly supports. Amen."),
"以特买": dict(lesson="A nameless one on the roll of mighty men",
 summary="A Moabite, one of David's mighty men.",
 witness="Ithmah was one on David's list of mighty men (a Moabite, from a Gentile people). He has no earth-shaking deed recorded, yet was numbered among the warriors who risked their lives for David. On the roll of heroes he is a faithful yet 'nameless' member—on God's roll, the faithful are never left unrecorded.",
 follow=["Faithful in the team, though not singled out for praise","Crossing his origin, committed to the one he served"],
 caution=[],
 applications=["Willingly be a faithful member 'on the roll yet without a solo deed'","Cross the limits of origin, committed to God's work","Trust God's roll leaves no faithful one unrecorded"],
 prayer="Lord, Ithmah was on the roll of mighty men without an illustrious deed. Make me willingly a faithful, nameless member, crossing my origin committed to You, trusting Your roll remembers every faithful one. Amen."),
"希勒斯": dict(lesson="A faithful member on the roll of mighty men",
 summary="A Paltite, one of David's mighty men.",
 witness="Helez was one of David's mighty men (a Paltite/Pelonite), listed among the warriors who fought for David. He has no solo deed detailed, yet by loyalty and bravery joined the ranks of heroes. Those who quietly do their duty in the team, God records each of their names.",
 follow=["Quietly faithful in the team, sharing the battle"],
 caution=[],
 applications=["Willingly be a faithful member who doesn't seek the limelight","Bear the responsibility of one heart with others","Trust God records the name of every faithful and brave one"],
 prayer="Lord, Helez was on the roll of mighty men, faithfully fighting. Make me willingly a quietly faithful member, of one heart with others, knowing You remember every faithful one. Amen."),
"希莱": dict(lesson="A mighty man of Netophah, faithful and silent",
 summary="A Netophathite, one of David's mighty men.",
 witness="Heled was a Netophathite, one of David's mighty men. Like many of the warriors, his name is on the roll but his deeds are silent. He represents that group who risked their lives for the king yet are not known in detail to later ages—their faithfulness, God sees.",
 follow=["Serving faithfully in silence","Doing his part in the community"],
 caution=[],
 applications=["Even if not known in detail, willingly serve faithfully and bravely","Value 'being remembered by God' over 'being praised by people'","Do your silent part well in the team"],
 prayer="Lord, Heled was faithful yet silent. Make me willingly serve faithfully where no one knows, valuing being remembered by You over being praised, doing my part well in the community. Amen."),
"亚吉": dict(lesson="God can prepare refuge even in a Gentile's hand",
 summary="The Philistine king of Gath, to whom David fled when escaping Saul.",
 witness="Achish was the Philistine king of Gath. When David was at the end of his road he fled to him, and he not only took him in but gave him the city of Ziklag to live in. A Gentile king became the temporary refuge God prepared for the persecuted David—God's care often comes through unexpected people.",
 follow=["Treating the stranded and sojourning kindly with tolerance"],
 caution=["David here too once survived by a lie, a reminder to stay honest even in refuge"],
 applications=["Extend a receiving hand to the stranded and sojourning","See that God can also supply you through 'outsiders'","Keep honesty even in hard situations"],
 prayer="Lord, You prepared refuge for the fleeing David through the Gentile king Achish. Make me too one who receives the stranded, and trust Your care often comes from unexpected places. Amen."),
"哈嫩": dict(lesson="Mistaking goodwill, bringing shame and disaster on himself",
 summary="King of Ammon, who shamed David's envoys and triggered a war.",
 witness="Hanun was the son of Nahash king of Ammon. David sent envoys to console and pay respects, but he listened to slander, suspected the envoys were spies, shamed them, and shaved off half their beards. This one mistaken suspicion triggered a war, and Ammon was badly defeated. To take goodwill as malice costs greatly.",
 follow=[],
 caution=["Listening to slander, mistaking another's goodwill for malice","Responding to goodwill with shame, stirring an avoidable conflict"],
 applications=["Don't lightly believe provocation; first understand others with goodwill","When shown goodwill, don't suspiciously shame the other","Take responsibility for the consequences your suspicion may trigger"],
 prayer="Lord, Hanun mistook goodwill and shamed the envoys, bringing ruin on himself. Make me not heed slander or suspect rashly, but treat people with goodwill, lest a great disaster come from misunderstanding. Amen."),
"拿辖": dict(lesson="The arrogance of shaming people invites destruction",
 summary="King of Ammon who besieged Jabesh-gilead and was defeated by Saul.",
 witness="Nahash was king of Ammon who, besieging Jabesh-gilead, set as a condition of covenant the gouging out of every right eye to shame the whole city. His cruelty became the occasion of Saul's first victory after being made king—God used his arrogance to accomplish Israel's deliverance.",
 follow=[],
 caution=["Displaying power by shaming and trampling people's dignity","Bullying those in desperation, powerless to resist"],
 applications=["Never display your strength by shaming others","Regard the dignity of those in desperation","Trust God can overturn the schemes the arrogant set"],
 prayer="Lord, Nahash showed off by shaming people and was finally defeated. Make me respect everyone's dignity, never lord it over people by force, and save all who fall into desperation. Amen."),
"以未米罗达": dict(lesson="One thought of mercy, a faint light in the dark",
 summary="King of Babylon who released the imprisoned Jehoiachin and treated him kindly.",
 witness="Evil-merodach was king of Babylon who, on coming to the throne, took the Judean king Jehoiachin out of prison after thirty-seven years, gave him a high seat, and dined with him until his death. In the long darkness of exile, this one thought of mercy was like a beam of light, foreshadowing that God's mercy toward His people had not ended.",
 follow=["Treating the stranded and imprisoned kindly with mercy","Showing mercy while in power"],
 caution=["While treating people kindly, still fear the God who gives authority"],
 applications=["Use your power or influence to treat the stranded kindly","Bring a beam of light into the 'prison' lows of others","Trust God's mercy still works in the dark"],
 prayer="Lord, through Evil-merodach You treated the imprisoned Jehoiachin kindly, showing mercy in the dark. Make me too treat the stranded with mercy, a faint light conveying Your mercy. Amen."),
"苏撒拿": dict(lesson="One of the women who supplied the Lord with their means",
 summary="One of the women who supplied Jesus and the disciples' needs.",
 witness="Susanna was one of the women who followed Jesus and supplied the Lord and the disciples from their own means, named by Luke with Mary Magdalene and Joanna. Their supply quietly held up the Lord's preaching team. Besides these named, there were 'many other women'—those who serve the Lord never lack such quiet givers.",
 follow=["Supplying the Lord's work with her own means","Quietly giving behind the scenes, holding up the ministry"],
 caution=[],
 applications=["Supply God's ministry with money and resources","Value supply-type service behind the scenes","Give and serve together with like-minded sisters"],
 prayer="Lord, Susanna supplied Your preaching work with her means. Make me too willingly supply Your ministry with resources, giving quietly behind the scenes, holding up Your work. Amen."),
"尼禄": dict(lesson="The fire of persecution cannot burn up the gospel",
 summary="The Roman emperor (Caesar) to whom Paul appealed, traditionally the emperor at Paul's martyrdom.",
 witness="Nero was the Roman emperor to whom Paul appealed; traditionally both Paul and Peter were martyred under his persecution. This emperor, known for cruelty, tried to extinguish the faith by fire and sword, yet the gospel burned all the brighter. The fiercest persecution cannot stop the expansion of God's kingdom.",
 follow=[],
 caution=["Persecuting the faith by power and violence","Thinking he could extinguish truth by force"],
 applications=["Hold your faith under persecution and pressure, not shrinking back","Trust the gospel's power surpasses all force","Pray for believers persecuted today"],
 prayer="Lord, Nero's persecution could not burn up Your gospel. Strengthen all believers under pressure and persecution, and make me firmly trust Your kingdom surpasses all the world's powers. Amen."),
"迷失的羊": dict(lesson="One lost sheep, the shepherd leaves the ninety-nine to seek",
 summary="The lost and found sheep in the parable, symbolizing a sinner's repentance and the shepherd's seeking.",
 witness="The lost sheep is the lead figure in Jesus' parable: of a hundred sheep, one strays, and the good shepherd leaves the ninety-nine to find the lost one, and finding it, joyfully carries it home on his shoulders. Jesus said there is such joy in heaven over one sinner who repents. Every stray sheep, in the shepherd's eyes, is worth seeking back.",
 follow=["Like the lost sheep, willingly let the shepherd seek you back","Imitate the good shepherd, going to seek the lost"],
 caution=["Don't stray far from the flock and wander off alone"],
 applications=["Trust that when you stray, the Lord will leave the ninety-nine to seek you","Go seek those who are lost and have gone astray","Truly rejoice over one sinner's repentance"],
 prayer="Lord, You are the good shepherd who leaves the ninety-nine to seek one lost sheep. Seek me back in my every straying, and give me a shepherd's heart to go seek the lost. Amen."),
"讥诮的强盗": dict(lesson="So near, yet mocking salvation",
 summary="The other robber crucified with Jesus who mocked the Lord.",
 witness="He was crucified with Jesus, yet joined others in mocking: 'Are you not the Christ? Save yourself and us!' The Savior was right beside him, yet he replaced pleading with mockery. In the same situation, the repentant robber gained paradise, but he missed it in his scorn. Even the one nearest salvation can harden his heart and miss it.",
 follow=[],
 caution=["Treating Christ with mockery and testing","So near, yet hardening his heart and missing salvation"],
 applications=["Don't treat the Lord with mockery and doubt","While you still have the chance, humbly plead rather than scoff","Examine: I am near the Lord, but do I truly know Him?"],
 prayer="Lord, the mocking robber was right beside You yet missed paradise. Soften my heart, that I not treat You with doubt and mockery, but humbly plead with You while there is still time. Amen."),
"文士": dict(lesson="Knowing the law well, yet maybe missing the Lord of the law",
 summary="The scholars who copied and taught the law, often in conflict with Jesus.",
 witness="The scribes were experts who copied and taught the law, who should have known God's word best. Yet many scribes 'said but did not do,' binding heavy burdens on others while not lifting a finger themselves, and even joined the Pharisees in opposing and condemning Jesus. Those most familiar with Scripture can also pass by the Lord to whom Scripture points.",
 follow=["Valuing the knowledge and teaching of God's word (the good of their office)"],
 caution=["Saying but not doing, word and deed inconsistent","Adding burdens to people while unwilling to bear them","Familiar with Scripture yet opposing the Lord Scripture points to"],
 applications=["Don't only know God's word, but do it","Don't lay heavy yokes only on others","Let your knowledge of Scripture lead you to know the Lord Himself"],
 prayer="Lord, the scribes knew the law yet missed the Lord of the law. Make me not only know Your word but do it, not inconsistent in word and deed, letting my knowledge lead me to know You more. Amen."),
"法利赛人": dict(lesson="Keeping the outside strictly, yet neglecting the heart",
 summary="The Jewish sect that strictly kept the law's traditions, often rebuked by Jesus for hypocrisy.",
 witness="The Pharisees zealously kept the law and traditions and were highly respected in their day. Yet Jesus rebuked them many times: cleaning the outside of the cup while inside it is full of greed and self-indulgence; tithing mint and dill while neglecting justice, mercy, and faithfulness. Among them were also true seekers like Nicodemus and Paul—outward piety needs to be filled with inward reality.",
 follow=["Zealously pursuing holiness and obedience (the good of their intent)"],
 caution=["Focusing on the outside and rules, neglecting the heart and mercy","Hypocrisy, covering inner filth with an appearance of piety","Self-righteously judging and despising others"],
 applications=["Pursue an inside-out consistency, not surface piety","Don't neglect the 'weightier matters'—justice, mercy, faithfulness","Replace self-righteousness with humility, not despising others"],
 prayer="Lord, the Pharisees kept the outside but neglected the heart. Make me consistent inside and out, no hypocrisy, valuing justice, mercy, and faithfulness, replacing self-righteousness with humility. Amen."),
"撒都该人": dict(lesson="Taking only this life loses the hope of resurrection",
 summary="The priestly aristocratic sect that did not believe in resurrection.",
 witness="The Sadducees were the priestly aristocratic class of the day, controlling the temple, accepting only the five books of Moses, not believing in resurrection or angels. They tested Jesus with the puzzle of 'seven brothers married to one wife,' and the Lord answered: you are wrong, because you know neither the Scriptures nor the power of God. Those who believe only in this life and not in resurrection shut themselves into a small world.",
 follow=[],
 caution=["Not believing in resurrection or the supernatural, taking only the present reality","Testing and denying God's power with rational puzzles","Holding religious office yet missing true faith"],
 applications=["Hold the hope of resurrection and eternal life, not only this life","Both know the Scriptures and trust God's power, holding both","Don't let realism hollow out faith's transcendent dimension"],
 prayer="Lord, the Sadducees did not believe in resurrection and were told by You they knew neither the Scriptures nor the power. Make me hold the hope of resurrection, both knowing Your word and trusting Your power. Amen."),
"希律党人": dict(lesson="Political calculation, joining an opponent to harm the Lord",
 summary="The political group supporting the Herodian dynasty, who plotted with the Pharisees against Jesus.",
 witness="The Herodians were a pro-Roman political group supporting the Herodian dynasty. Though originally opposed to the Pharisees in stance, they joined hands to remove Jesus—'the Pharisees went out and took counsel with the Herodians how to destroy Him.' They also came to test the Lord with the question of taxes. When political calculation overrides truth, even former opponents can ally to remove Christ.",
 follow=[],
 caution=["Replacing loyalty to truth with political stance and calculation","Allying with an opponent to remove the thorn in their eye"],
 applications=["Don't let political stance override loyalty to truth","Beware alliances formed 'to deal with a certain person'","Judge right and wrong by truth, not self-interest"],
 prayer="Lord, the Herodians allied with opponents to destroy You. Make me not let political calculation override loyalty to You, judging by truth, not forming factions out of private grudges. Amen."),
"基比亚的利未人": dict(lesson="His own failure of duty brewed great chaos",
 summary="The Levite who, bringing his concubine home, met violence in Gibeah.",
 witness="He was the Levite passing through Gibeah with his concubine. When wicked men surrounded the house, he pushed his concubine out to take his place, letting her be abused to death, and afterward cut up her body and sent the pieces to the tribes to stir public outrage, triggering civil war. Though a victim's side, his self-preservation and coldness are not free of blame—in a lawless age, even a victim can lose his humanity.",
 follow=[],
 caution=["Pushing another into danger for self-preservation","Venting by extreme means, triggering greater bloodshed"],
 applications=["In peril, don't preserve yourself by sacrificing others","Handle wrongs by seeking justice, not inciting greater violence","Examine: has the spirit of a lawless age eroded my conscience too?"],
 prayer="Lord, the Levite of Gibeah pushed out his concubine for self-preservation, brewing great chaos. Keep my conscience from being eroded by a lawless age, not sacrificing others in peril, handling wrongs by seeking justice, not revenge. Amen."),
"利未人的妾": dict(lesson="A nameless victim in a dark age",
 summary="Who was abused to death in Gibeah, triggering a tribal civil war.",
 witness="She was the concubine of that Levite of Gibeah, who in the lawless age of the judges was abused to death by wicked men, triggering an Israelite civil war. Scripture truthfully records this tragedy precisely to show the darkness and cruelty of the age when 'there was no king in Israel; everyone did as he saw fit.'",
 follow=[],
 caution=["(An age's warning) the cruelty of being kingless and lawless, everyone doing as he saw fit","Indifference to and violence against the weak"],
 applications=["Mourn and intercede for the nameless harmed by violence","Hold justice in an atmosphere of 'everyone doing as he saw fit'","Be one who protects the weak, not one who is indifferent"],
 prayer="Lord, the violence at Gibeah took this nameless concubine's life. Have mercy on all harmed by violence, make me hold justice, a protector of the weak, not doing as I see fit in a lawless age. Amen."),
"希斯仑": dict(lesson="Quietly nameless, yet in the genealogy of salvation",
 summary="Son of Perez, a link in the line of Judah, David, and Christ.",
 witness="Hezron was the son of Perez. Scripture records almost none of his deeds, yet he is a link carrying forward the tribe of Judah, his name written steadily in the genealogy of David and Christ. God's plan of redemption was passed down generation by generation precisely through countless such people who 'left only a name.'",
 follow=["Faithfully carrying forward and back amid the ordinary, even the nameless","Valuing being 'remembered on God's roll' over being remembered by people"],
 caution=["Not despising your place because you are unnoticed"],
 applications=["Be faithful in an inconspicuous role; you too are in God's story","Value the responsibility of passing faith to the next generation","Trust God remembers everyone who quietly does their duty"],
 prayer="Lord, though Hezron is quietly nameless, he is in Your genealogy of salvation. Make me content in my ordinary duty, faithfully carrying it on, knowing You remember my name. Amen."),
"兰": dict(lesson="An invisible link in the genealogy",
 summary="Son of Hezron, a link in the Messianic line (also spelled Aram).",
 witness="Ram (also Aram) was the son of Hezron and the father of Amminadab, a link in the Messianic line. Scripture records almost none of his deeds, but without this link the chain from Perez to David to Christ would not connect. An invisible link is also indispensable.",
 follow=["Willingly an invisible yet indispensable link in the genealogy"],
 caution=["Not despising your worth because you are not recorded"],
 applications=["Be faithful in an unseen position; you too are in God's chain","Value the responsibility of carrying on and back","Trust God remembers every invisible link"],
 prayer="Lord, though Ram is hidden in the genealogy, he is an indispensable link. Make me willingly faithful in unseen places, knowing there is a link of mine in Your chain of salvation. Amen."),
"亚米拿达": dict(lesson="Preparing the way for the next generation",
 summary="Father of Nahshon, a link in the Messianic line.",
 witness="Amminadab was the son of Ram and the father of Nahshon, and his daughter Elisheba married Aaron as the high priest's wife. He has little recorded of his own, yet bore and connected the leaders of the exodus generation, preparing the way for the rise of the tribe of Judah.",
 follow=["Quietly raising and connecting, preparing the way for the next generation","Serving God's community through family connection"],
 caution=["Not despising the worth of paving the way for the next generation"],
 applications=["Quietly pave the way for the rise of the next generation","Value the family's connecting role in God's community","Trust your nurture today has far-reaching influence"],
 prayer="Lord, Amminadab prepared the way for the next generation's leaders. Make me faithfully raise and connect, paving the way for those who follow, a hidden blessing in Your work. Amen."),
"拿顺": dict(lesson="Leading the way in following, a model for the community",
 summary="Leader of the tribe of Judah, a link in the Messianic line.",
 witness="Nahshon was the leader of the tribe of Judah; when Israel broke camp and set out in the wilderness, the camp of Judah always set out first to follow God's leading, and he was first to offer his altar gifts. He is a link in Christ's genealogy, and even more a model of 'leading in obedience'—while others watched, he stepped out first.",
 follow=["Leading in obedience and following first in the community","Being an example to others by action"],
 caution=["Not retreating to watch from behind when one should lead"],
 applications=["When someone needs to step out first, willingly be that one","Lead by example, moving those around you to follow God","Treat 'leading' as a responsibility, not a glory"],
 prayer="Lord, Nahshon led in following Your guidance and offered first. Make me a model of obedience in the community, stepping out first while others watch, glorifying You by action. Amen."),
"撒门": dict(lesson="Marrying the Gentile Rahab, grace comes into the genealogy",
 summary="Father of Boaz, who married Rahab, a link in the Messianic line.",
 witness="Salmon was the son of Nahshon and the father of Boaz. By tradition, he married Rahab the prostitute of Jericho—a Gentile woman brought into God's people by faith. Through this marriage, grace and a Gentile were woven together into the Messiah's genealogy.",
 follow=["Receiving those who come to the Lord by faith, regardless of origin","Letting grace cross the boundaries of status and race"],
 caution=["Not judging by origin those whom God receives"],
 applications=["Receive and respect those of different origins who come to the Lord by faith","See that God's genealogy is full of grace and acceptance","Don't let prejudice keep you from receiving those God receives"],
 prayer="Lord, Salmon married the converted Rahab, and grace came into the genealogy. Remove prejudice from my heart, that I receive all who come to You by faith, as You received me. Amen."),
"撒拉铁": dict(lesson="In exile, the line was still unbroken",
 summary="Son of Jehoiachin, father of Zerubbabel, a link in the line after the exile.",
 witness="Shealtiel was the son of the exiled king Jehoiachin and the father of Zerubbabel. The nation broken, the dynasty seemingly cut off, yet David's lamp was not extinguished—this line passed through the darkness of exile and reached all the way to Christ. God's promise cannot be hidden even by darkness.",
 follow=["Holding identity and hope amid the nation's darkness and lows"],
 caution=["Not despairing in circumstances and thinking God's promise has failed"],
 applications=["In your life's 'exile' lows, hold the promise God gave you","Trust God's plan can pass through the darkest time","Keep the lamp of faith for your family and the next generation"],
 prayer="Lord, Shealtiel carried on David's line in exile, and Your lamp is never extinguished. Make me hold hope in dark lows, firmly trusting Your promise will surely not fail. Amen."),
}
